  "Du": "Tu",
  "Du behöver ett koppel – köp ett i djuraffären.": "Ti serve un guinzaglio – compralo al Negozio Animali.",
  "Du behöver tjäna <b>{0}</b> till – ungefär <b>{1} pass</b> (≈ {2} per pass).": "Devi guadagnare ancora <b>{0}</b> – circa <b>{1} turni</b> (≈ {2} a turno).",
