  "Du blir bättre på {0}: {1}!": "Stai migliorando con {0}: {1}!",
  "Du bor ihop med {0} – flytta isär först (👥 i menyraden).": "Vivi con {0} – prima separatevi (👥 nella barra del menu).",
  "Du bor redan här.": "Abiti già qui.",
  "Du bär ingenting.": "Non hai niente in mano.",
  "Du bär på <b>{0}</b> ({1}) som inte är betald.": "Hai in mano <b>{0}</b> ({1}) e non l'hai ancora pagato.",
  "Du flyttar tillbaka till {0} med dina gamla möbler.": "Torni nella tua casa di prima ({0}) con i tuoi vecchi mobili.",
  "Du får <b>{0}</b> nu. Betala tillbaka <b>{1}</b> (lånet + {2} % ränta) senast <b>{3}</b> så får du tillbaka möbeln. Annars behåller pantbanken den.": "Ricevi <b>{0}</b> ora. Restituisci <b>{1}</b> (prestito + {2} % di interessi) entro <b>{3}</b> e riavrai il mobile. Altrimenti se lo tiene il Monte dei Pegni.",
  "Du får den i handen och sätter dig vid bistroborden här bredvid – mättheten kommer medan du äter.": "Te lo danno in mano e ti siedi ai tavolini del bistrò qui accanto – la sazietà arriva mentre mangi.",
  "Du får en bricka och sätter dig vid ett ledigt bord. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Prendi un vassoio e ti siedi a un tavolo libero. Sazietà ed energia arrivano mentre mangi – solo da seduti!",
