  "För sent att börja ett pass – jobben öppnar 07:00 igen.": "Troppo tardi per iniziare un turno – i lavori riaprono alle 07:00.",
  "För sent – lånet har förfallit och möbeln är pantbankens.": "Troppo tardi – il prestito è scaduto e il mobile è del Monte dei Pegni.",
  "Förbipasserande köper allt du ställer ut. Ägg och mjölk tas ur skafferiet – spara det du vill laga mat av!": "Chi passa compra tutto quello che metti in vendita. Uova e latte si prendono dalla dispensa – tieni da parte quello che vuoi cucinare!",
