  "Välj": "Scegli",
  "Välj din avatar eller skapa en ny.": "Scegli il tuo avatar o creane uno nuovo.",
  "Välj en fröpåse. Vattna bädden varje dag – två dagar utan vatten och plantorna vissnar. Skörden hamnar i skafferiet.": "Scegli una bustina di semi. Annaffia l'aiuola ogni giorno – due giorni senz'acqua e le piantine si seccano. Il raccolto finisce in dispensa.",
  "Välj en häst.": "Scegli un cavallo.",
  "Välj en låt – den går hemma tills du stänger av eller lägger dig. Alla låtar i Pixelstaden finns här.": "Scegli una canzone – suona in casa finché non la spegni o vai a dormire. Qui ci sono tutte le canzoni di Pixelopoli.",
  "Välj en möbel först": "Prima scegli un mobile",
  "Välj en ny frisyr eller färg först.": "Prima scegli una nuova pettinatura o un colore.",
  "Välj en ny frisyr eller hårfärg – förhandsbilden visar hur det blir på dig.": "Scegli una nuova acconciatura o un nuovo colore – l'anteprima ti mostra come ti sta.",
  "Välj ett belopp.": "Scegli un importo.",
  "Välj ett ställe på kartan.": "Scegli un posto sulla mappa.",
  "Välj hur högt du siktar i varje mål. Du har klarat livet i Pixelstaden när alla fyra är nådda samtidigt.": "Scegli quanto in alto punti per ogni obiettivo. Hai vinto la vita a Pixelopoli quando li raggiungi tutti e quattro insieme.",
  "Välj hur mycket du vill sätta in.": "Scegli quanto vuoi versare.",
  "Välj hur mycket du vill ta ut.": "Scegli quanto vuoi prelevare.",
  "Välj något från menyn först!": "Prima scegli qualcosa dal menù!",
  "Välj något i butiken så slår jag in det!": "Scegli qualcosa in negozio e io te lo batto in cassa!",
