  "💬 Alla djur här är ungar. De växer av mat, lek, en leksak och rätt toalett – tidigast unga efter 3 dagar och vuxna efter en vecka.": "💬 Qui tutti gli animali sono cuccioli. Crescono con cibo, gioco, un giocattolo e il posto giusto per i bisogni – diventano giovani dopo almeno 3 giorni e adulti dopo una settimana.",
  "💬 Djuren har en liten mätare ovanför sig: hjärtat är glädje och skålen är hunger.": "💬 Gli animali hanno un piccolo indicatore sopra la testa: il cuore è la felicità e la ciotola è la fame.",
